#include <iostream>

namespace domain { struct Order { int item_count; }; }
namespace service { bool can_submit(const domain::Order& order) { return order.item_count > 0; } }
int main() {
    const domain::Order order{3};
    std::cout << std::boolalpha << service::can_submit(order) << '\n';
}
